import {paint,appearanceMarkup,installDesignEvents} from '/design.js';
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'▦',package:'▣',orders:'▤',users:'♧',tag:'◇',layers:'▱',list:'☷',ticket:'▧',bolt:'ϟ',spark:'✧',star:'☆',mail:'✉',store:'⌂',wallet:'▰',truck:'↗',cart:'⊞',percent:'%',return:'↶',file:'▯',edit:'✎',image:'▧',help:'?',quote:'❞',bell:'♧',shield:'♢',plug:'⌘',globe:'◎',link:'↗',history:'◷',chart:'▥',themes:'◐',pos:'⊞',settings:'⚙'};
const icon=k=>`<span class="icon">${icons[k]||'◇'}</span>`;
let boot,adminBoot,csrf='',currentModule='dashboard',records=[],recordPage=1,recordSearch='',adminCache={},quoteData=null,lastReceipt=null;
let cart;try{cart=JSON.parse(localStorage.getItem('astrallab-cart')||'[]')}catch{cart=[]}if(!Array.isArray(cart))cart=[];
let posCart=[],activeDialog=null,customerRegister=false;
const money=(value,cents=false)=>new Intl.NumberFormat('en-BD',{style:'currency',currency:boot?.store.currency||'BDT',maximumFractionDigits:0}).format(Number(value||0)/(cents?100:1));
const date=v=>v?new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
const badge=v=>`<span class="badge ${esc(v)}">${esc(String(v||'draft').replaceAll('_',' '))}</span>`;
const toast=(message,error=false)=>{const node=$('#toast');node.textContent=message;node.classList.toggle('error',error);node.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.hidden=true,4500)};
async function api(url,method='GET',data){const response=await fetch(url,{method,headers:{'Content-Type':'application/json',...(method==='GET'?{}:{'X-CSRF-Token':csrf})},body:data===undefined?undefined:JSON.stringify(data)});let body;try{body=await response.json()}catch{body={error:'Invalid server response'}}if(!response.ok)throw Object.assign(Error(body.error||'Request failed'),{status:response.status});return body}
function go(url){history.pushState(null,'',url);window.scrollTo(0,0);render().catch(e=>toast(e.message,true))}
function errorBox(message){return `<div class="empty"><span>◇</span><h3>We couldn’t open this page</h3><p>${esc(message)}</p><button class="btn" data-go="/">Back to storefront</button></div>`}
const productById=id=>boot.products.find(p=>p.id===Number(id));
function cartSave(){localStorage.setItem('astrallab-cart',JSON.stringify(cart));quoteData=null}
function addCart(id,variantId=null){const p=productById(id);if(!p)return;const existing=cart.find(x=>x.product_id===p.id&&x.variant_id===variantId);if(existing)existing.quantity++;else cart.push({product_id:p.id,variant_id:variantId,quantity:1});cartSave();toast(p.name+' added to your bag');if($('.bag-count'))$('.bag-count').textContent=cart.reduce((s,x)=>s+x.quantity,0)}
function theme(){const preview=new URLSearchParams(location.search).get('preview_layout');const selected=boot.canPreview&&preview?preview:(boot.appearance?.frontend.layout||boot.store.theme);return boot.themes.find(t=>t.id===selected)||boot.themes[0]}
function productCard(p){return `<article class="product-card"><a data-nav href="/product/${esc(p.slug)}" class="product-picture"><img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy"><span class="product-label">${p.tags?.includes('new')?'NEW ARRIVAL':p.featured==='yes'?'THE EDIT':'ESSENTIAL'}</span><button class="quick-add" data-add="${p.id}" aria-label="Add ${esc(p.name)} to bag">+</button></a><div class="product-category">${esc(boot.categories.find(c=>c.id===p.category_id)?.name||'The collection')}</div><a data-nav href="/product/${esc(p.slug)}"><h3>${esc(p.name)}</h3></a><div class="product-price">${money(p.sale_price??p.price)}${p.sale_price&&p.sale_price<p.price?` <del>${money(p.price)}</del>`:''}<span class="product-stars" title="${boot.reviews.filter(r=>r.product_id===p.id).length} published reviews">${boot.reviews.some(r=>r.product_id===p.id)?"★ "+(boot.reviews.filter(r=>r.product_id===p.id).reduce((sum,r)=>sum+r.rating,0)/boot.reviews.filter(r=>r.product_id===p.id).length).toFixed(1):""}</span></div></article>`}
function storefrontShell(content){const t=theme();const total=cart.reduce((s,x)=>s+x.quantity,0);
 return `<div class="storefront theme-${t.layout}"><div class="announcement">${esc(boot.announcements[0]?.name||'A thoughtful store. An extraordinary everyday.')} <span>↗</span></div><header class="store-header"><a class="store-brand" href="/" data-nav><span class="logo-mark">A</span><span>ASTRALLAB<small>ULTIMATE ECOMMARCE</small></span></a><nav class="store-nav"><a data-nav href="/shop">Shop all</a><a data-nav href="/shop?filter=new">New arrivals <span class="nav-new">NEW</span></a><a data-nav href="/journal">Journal</a><a data-nav href="/page/our-story">Our story</a></nav><div class="store-tools"><a data-nav href="/track" title="Track order">${icon('truck')}</a><a data-nav href="/account" title="My account">${icon('users')}</a><a data-nav href="/cart" class="bag-link">Bag <span class="bag-count">${total}</span></a><a class="admin-link" href="/demo">Admin demo ↗</a></div></header>${content}<section class="newsletter"><div><span class="eyebrow">A NOTE FROM ASTRALLAB</span><h2>A little inspiration.<br>Delivered occasionally.</h2></div><form id="subscribe-form"><label for="subscribe-email">Good things are worth sharing.</label><div><input id="subscribe-email" name="email" type="email" placeholder="Your email address" required><button aria-label="Subscribe">↗</button></div><small>No noise. Just new arrivals, thoughtful stories, and a little something extra.</small></form></section><footer class="store-footer"><div><a class="store-brand" data-nav href="/"><span class="logo-mark">A</span><span>ASTRALLAB<small>ULTIMATE ECOMMARCE</small></span></a><p>${esc(boot.store.tagline)}</p><small>Designed to connect. Built to grow.</small></div><div><h4>Discover</h4><a data-nav href="/shop">The collection</a><a data-nav href="/journal">The journal</a><a data-nav href="/page/our-story">Our story</a></div><div><h4>Here to help</h4><a data-nav href="/track">Track your order</a><a data-nav href="/page/shipping-returns">Shipping & returns</a><a data-nav href="/contact">Contact us</a></div><div><h4>Your workspace</h4><a href="/demo">Open admin demo ↗</a><small>Local demo · no live payment charges</small></div><div class="copyright"><span>© ${new Date().getFullYear()} Ultimate Ecommarce By Astrallab.</span><span>Thoughtfully built. Endlessly adaptable. <b>✧</b></span></div></footer></div>`;
}
function home(){const t={...theme()};const banner=boot.sliders[0];if(banner&&banner.headline!=="Good things. Great possibilities."){t.headline=banner.headline;t.description=banner.description;}return storefrontShell(`<section class="hero"><div class="hero-copy"><span class="eyebrow">${esc(t.tag)}</span><h1>${esc(t.headline).replace('\n','<br>')}</h1><p>${esc(t.description)}</p><div class="hero-actions"><a data-nav href="/shop" class="btn dark">Shop the collection <span>↗</span></a><a data-nav href="/page/our-story" class="underlined">Our story</a></div><div class="hero-social"><span class="mini-avatars"><i>A</i><i>R</i><i>N</i></span><div><b>Thoughtful products. Happy people.</b><small>Discover a store built around you.</small></div></div></div><div class="hero-visual"><span class="hero-orbit"></span><span class="hero-watermark">the<br>everyday<br>edit.</span><img class="hero-product" src="${esc(boot.sliders[0]?.image||"/assets/product-4.png")}" alt="Signature jacket from the Astrallab collection"><div class="floating-note"><span>✧</span><div>Considered, not complicated.<small>Quality you can feel.</small></div></div><span class="hero-season">COLLECTION 01 / EVERYDAY</span></div></section><div class="benefits"><span>${icon('truck')} Free delivery over ${money(5000)}</span><span>${icon('shield')} Thoughtfully selected quality</span><span>${icon('return')} Easy returns & support</span><span>${icon('spark')} Friendly support, every day.</span></div><section class="store-section"><div class="section-heading"><div><span class="eyebrow">FIND YOUR EVERYDAY</span><h2>Good things, by category.</h2></div><a data-nav href="/shop" class="underlined">Explore everything ↗</a></div><div class="category-grid">${boot.categories.map((c,i)=>`<a data-nav href="/shop?category=${c.id}" class="category-card category-${i}"><div><h3>${esc(c.name)}</h3><span>${boot.products.filter(p=>p.category_id===c.id).length} thoughtful finds ↗</span></div><img src="${esc(c.image)}" alt="${esc(c.name)}" loading="lazy"></a>`).join('')}</div></section><section class="store-section collection-section"><div class="section-heading"><div><span class="eyebrow">THE ASTRALLAB EDIT</span><h2>Your next favorites.</h2></div><div class="collection-tabs"><button class="active" data-home-filter="all">The essentials</button><button data-home-filter="new">Just landed</button><a data-nav href="/shop">View all ↗</a></div></div><div id="home-products" class="product-grid">${boot.products.slice(0,8).map(productCard).join('')}</div></section><section class="story-banner"><div><span class="eyebrow">SMALL DETAILS. BIG DIFFERENCE.</span><h2>Made for the way<br>you live.</h2><p>Beautifully considered essentials. A simpler way to shop. One connected experience, from discovery to delivery.</p><a data-nav href="/shop" class="btn light">Discover your essentials ↗</a></div><div class="story-images"><img src="/assets/product-1.png" alt="Everyday essentials"><img src="/assets/product-7.png" alt="Weekend layers"></div><span class="story-star">✳</span></section><section class="store-section journal-preview"><div class="section-heading"><div><span class="eyebrow">MORE THAN A STORE</span><h2>A little perspective.</h2></div><a data-nav href="/journal" class="underlined">Read the journal ↗</a></div>${boot.posts.slice(0,1).map(p=>`<a data-nav href="/journal/${esc(p.slug)}" class="journal-feature"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><span class="eyebrow">THE EVERYDAY JOURNAL</span><h3>${esc(p.name)}</h3><p>${esc(p.content).slice(0,180)}</p><span class="underlined">Read the story ↗</span></div></a>`).join('')}</section>`)}
function shopPage(){const query=new URLSearchParams(location.search);const category=query.get('category');const q=query.get('q')||'';const filtered=boot.products.filter(p=>(!category||p.category_id===Number(category))&&(!q||(p.name+' '+p.description).toLowerCase().includes(q.toLowerCase()))&&(!query.get('filter')||p.tags?.includes(query.get('filter'))));return storefrontShell(`<section class="shop-title"><span class="eyebrow">THE COMPLETE COLLECTION</span><h1>Find your everyday.</h1><p>Thoughtful essentials. Endless possibilities.</p></section><section class="store-section shop-layout"><aside class="shop-filters"><h3>Shop by category</h3><a data-nav class="${!category?'active':''}" href="/shop">All products <span>${boot.products.length}</span></a>${boot.categories.map(c=>`<a data-nav class="${category==c.id?'active':''}" href="/shop?category=${c.id}">${esc(c.name)} <span>${boot.products.filter(p=>p.category_id===c.id).length}</span></a>`).join('')}<div class="filter-note">✧<h4>The welcome edit</h4><p>Enjoy 10% off your first order above ${money(1000)}.</p><b>WELCOME10</b></div></aside><div><div class="shop-toolbar"><span>${filtered.length} products</span><form id="shop-search"><input name="q" placeholder="Find something you’ll love…" value="${esc(q)}"><button aria-label="Search products">⌕</button></form><select id="product-sort" aria-label="Sort products"><option value="default">Curated for you</option value="low">Price: low to high</option value="high">Price: high to low</option><option value="name">Name A–Z</option></select></div><div id="shop-products" class="product-grid">${filtered.length?filtered.map(productCard).join(''):'<div class="empty"><h3>No finds just yet.</h3><p>Try another category or search.</p></div>'}</div></div></section>`)}
function productPage(slug){const p=boot.products.find(p=>p.slug===slug);if(!p)return storefrontShell(errorBox('This product is not available.'));const reviews=boot.reviews.filter(r=>r.product_id===p.id);const variants=(boot.variants||[]).filter(v=>v.product_id===p.id);return storefrontShell(`<section class="store-section"><div class="breadcrumbs"><a data-nav href="/shop">Collection</a> / ${esc(p.name)}</div><div class="product-detail"><div class="detail-image"><img src="${esc(p.image)}" alt="${esc(p.name)}"></div><div class="detail-copy"><span class="eyebrow">THE ASTRALLAB EDIT</span><h1>${esc(p.name)}</h1><div class="detail-price">${money(p.sale_price??p.price)}</div><p>${esc(p.description)}</p><div class="stock-indicator"><i></i>${p.stock>0?`${p.stock} available · Ready for your everyday`:'Currently out of stock'}</div>${variants.length?`<label>Choose your option<select id="variant-select"><option value="">Standard</option>${variants.map(v=>`<option value="${v.id}">${esc(v.name)} · ${money(v.price)}</option>`).join('')}</select></label>`:''}<button class="btn dark full" data-detail-add="${p.id}" ${p.stock<1?'disabled':''}>Add to bag <span>＋</span></button><div class="detail-benefits"><span>↗ Standard delivery in 3 days</span><span>↶ Friendly returns & support</span><span>♢ Cash on delivery available</span></div><details open><summary>The details</summary><p>SKU: ${esc(p.sku)}<br>Category: ${esc(boot.categories.find(c=>c.id===p.category_id)?.name)}<br>${esc(p.description)}</p></details><details><summary>Shipping & returns</summary><p>Standard shipping is ${money(80)}. Free on orders above ${money(5000)}. Contact our team for returns.</p></details></div></div><div class="section-heading related-heading"><h2>You might also love.</h2><a data-nav href="/shop" class="underlined">View everything ↗</a></div><div class="product-grid">${boot.products.filter(x=>x.id!==p.id).slice(0,4).map(productCard).join('')}</div><section class="reviews-section"><h2>From the community</h2>${reviews.length?reviews.map(r=>`<article><b>${esc(r.name)}</b><span>${'★'.repeat(r.rating)}</span><p>${esc(r.comment)}</p></article>`).join(''):'<p>Be the first to share your experience. Reviews are moderated in the admin workspace.</p>'}</section></section>`)}
async function cartPage(checkout=false){cart=cart.filter(i=>productById(i.product_id));let error='';if(cart.length){try{quoteData=await api('/api/quote','POST',{items:cart,coupon:sessionStorage.getItem('astrallab-coupon')||'',shipping_id:Number(sessionStorage.getItem('astrallab-shipping')||boot.shipping[0]?.id)})}catch(e){quoteData=null;error=e.message}}
 return storefrontShell(`<section class="store-section"><div class="page-heading"><span class="eyebrow">A LITTLE SOMETHING FOR YOU</span><h1>${checkout?'Make it yours.':'Your shopping bag.'}</h1><p>${cart.length?'Thoughtfully chosen. Ready when you are.':'Your next favorite is waiting in the collection.'}</p></div>${!cart.length?`<div class="empty"><span>＋</span><a data-nav href="/shop" class="btn dark">Explore the collection ↗</a></div>`:`<div class="checkout-layout"><div>${checkout?`<form id="checkout-form" class="checkout-form"><h2>Where should we send it?</h2><div class="form-grid">${field('customer_name','Full name','text',boot.customer?.name||'',true)}${field('email','Email','email',boot.customer?.email||'',true)}${field('phone','Phone','tel',boot.customer?.phone||'',true)}${field('address','Delivery address','text',boot.customer?.address||'',true)}<label class="wide">Order notes<textarea name="notes" placeholder="Anything we should know?"></textarea></label></div><h2>Payment</h2><div class="payment-option"><input type="radio" checked disabled> Cash on delivery <span>No online charge</span></div><p class="muted">This local demo records your order. Live payment providers can be configured in Integrations.</p><button class="btn dark full" ${!quoteData?'disabled':''}>Place order · ${money(quoteData?.total,true)} ↗</button><p class="form-error">${esc(error)}</p></form>`:cart.map((item,i)=>{const p=productById(item.product_id);return `<article class="cart-row"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><a data-nav href="/product/${esc(p.slug)}"><h3>${esc(p.name)}</h3></a><small>${esc(p.sku)}</small><span>${money(p.sale_price??p.price)}</span></div><div class="qty"><button data-cart-qty="${i}" data-delta="-1">−</button><b>${item.quantity}</b><button data-cart-qty="${i}" data-delta="1">+</button></div><button class="remove-item" data-cart-remove="${i}" aria-label="Remove ${esc(p.name)}">×</button></article>`}).join('')}</div><aside class="order-summary"><h2>The good things inside.</h2><div class="summary-items">${cart.map(i=>`<p><span>${esc(productById(i.product_id).name)} × ${i.quantity}</span></p>`).join('')}</div><form id="coupon-form"><input name="coupon" placeholder="Have a welcome code?" value="${esc(sessionStorage.getItem('astrallab-coupon')||'')}"><button>Apply</button></form><label class="shipping-label">Delivery<select id="shipping-select">${boot.shipping.map(s=>`<option value="${s.id}" ${Number(sessionStorage.getItem('astrallab-shipping')||boot.shipping[0]?.id)===s.id?'selected':''}>${esc(s.name)} · ${money(s.price)}</option>`).join('')}</select></label>${error?`<p class="form-error">${esc(error)}</p>`:''}<div class="summary-line"><span>Subtotal</span><b>${money(quoteData?.subtotal,true)}</b></div><div class="summary-line"><span>Welcome savings</span><b>−${money(quoteData?.discount,true)}</b></div><div class="summary-line"><span>Delivery</span><b>${money(quoteData?.shipping,true)}</b></div><div class="summary-line"><span>Tax</span><b>${money(quoteData?.tax,true)}</b></div><div class="summary-line total"><span>Total</span><b>${money(quoteData?.total,true)}</b></div>${!checkout?`<a class="btn dark full" data-nav href="/checkout">Continue to checkout ↗</a>`:''}<small>♢ A simple, secure local checkout.</small></aside></div>`}</section>`)}
function field(name,label,type='text',value='',required=false){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`}
function accountPage(){return storefrontShell(`<section class="store-section narrow"><span class="eyebrow">YOUR ASTRALLAB</span><h1>${boot.customer?'Hello, '+esc(boot.customer.name)+'.':customerRegister?'Make yourself at home.':'Good to see you again.'}</h1>${boot.customer?`<p>${esc(boot.customer.email)}</p><div id="account-orders">Loading your orders…</div><button class="btn outline" id="customer-logout">Sign out</button>`:`<form id="customer-form" class="stack-form">${customerRegister?field('name','Full name','text','',true):''}${field('email','Email','email','',true)}${field('password','Password (at least 8 characters)','password','',true)}<button class="btn dark">${customerRegister?'Create account':'Sign in'} ↗</button><p class="form-error"></p></form><button id="customer-toggle" class="text-btn">${customerRegister?'Already a member? Sign in':'New here? Create an account'}</button>`}</section>`)}
function contentPage(){const path=location.pathname;const parts=path.split('/');if(path==='/track')return storefrontShell(`<section class="store-section narrow"><span class="eyebrow">FROM US TO YOU</span><h1>Follow the good things.</h1><p>Enter the order number and email used at checkout.</p><form id="track-form" class="stack-form">${field('number','Order number','text','',true)}${field('email','Checkout email','email','',true)}<button class="btn dark">Track order ↗</button><p class="form-error"></p></form><div id="track-result"></div></section>`);
 if(path==='/contact')return storefrontShell(`<section class="store-section narrow"><span class="eyebrow">LET’S TALK</span><h1>We’re here for you.</h1><p>${esc(boot.store.email)} · ${esc(boot.store.phone)}</p><form id="contact-form" class="stack-form">${field('subject','Subject','text','',true)}${field('email','Your email','email','',true)}<label>Your message<textarea name="message" required></textarea></label><button class="btn dark">Send message ↗</button><p class="form-error"></p></form></section>`);
 if(path==='/journal')return storefrontShell(`<section class="store-section"><div class="page-heading"><span class="eyebrow">THE ASTRALLAB JOURNAL</span><h1>A little perspective.</h1></div><div class="journal-grid">${boot.posts.map(p=>`<a data-nav href="/journal/${esc(p.slug)}"><img src="${esc(p.image)}" alt="${esc(p.name)}"><h2>${esc(p.name)}</h2><p>${esc(p.content).slice(0,150)}</p></a>`).join('')}</div></section>`);
 const post=(parts[1]==='journal'?boot.posts:boot.pages).find(p=>p.slug===parts[2]);if(!post)return storefrontShell(errorBox('This page has not been published.'));
 let sections;try{sections=JSON.parse(post.content);if(!Array.isArray(sections))sections=null}catch{}
 return storefrontShell(`<article class="store-section content-page"><div class="page-heading"><span class="eyebrow">${parts[1]==='journal'?'THE JOURNAL':'ASTRALLAB'}</span><h1>${esc(post.name)}</h1></div>${sections?sections.map(s=>sectionHtml(s)).join(''):`${post.image?`<img class="content-cover" src="${esc(post.image)}" alt="${esc(post.name)}">`:''}<div class="prose">${esc(post.content).split('\n').map(p=>`<p>${p}</p>`).join('')}</div>`}</article>`)}
function sectionHtml(s){if(s.type==='products')return `<section><h2>${esc(s.title||'The collection')}</h2><div class="product-grid">${boot.products.slice(0,4).map(productCard).join('')}</div></section>`;if(s.type==='hero')return `<section class="builder-hero"><h2>${esc(s.title)}</h2><p>${esc(s.body)}</p>${s.image?`<img src="${esc(s.image)}" alt="${esc(s.title)}">`:''}</section>`;if(s.type==='cta')return `<section class="builder-cta"><h2>${esc(s.title)}</h2><p>${esc(s.body)}</p><a data-nav class="btn dark" href="/shop">Explore the collection ↗</a></section>`;return `<section class="prose"><h2>${esc(s.title)}</h2><p>${esc(s.body).replaceAll('\n','<br>')}</p></section>`}
function receiptPage(){const r=lastReceipt||JSON.parse(sessionStorage.getItem('astrallab-last-order')||'null');return storefrontShell(`<section class="store-section narrow receipt"><span class="success-circle">✓</span><span class="eyebrow">A LITTLE HAPPINESS IS ON ITS WAY</span><h1>Thank you${r?', '+esc(r.customer_name.split(' ')[0]):''}.</h1><p>Your order has been saved to the shared backend.</p>${r?`<div class="receipt-box"><h2>${esc(r.number)}</h2><p>${esc(r.email)}</p>${r.items.map(i=>`<div class="summary-line"><span>${esc(i.name)} × ${i.quantity}</span><b>${money(i.unit_price*i.quantity,true)}</b></div>`).join('')}<div class="summary-line total"><span>Total</span><b>${money(r.total,true)}</b></div>${badge(r.status)}</div>`:''}<a data-nav href="/track" class="btn dark">Track your order ↗</a><a data-nav href="/shop" class="text-btn">Keep discovering</a></section>`)}

function adminShell(content){const permissions=adminBoot.user.permissions;const allowed=id=>permissions.includes('*')||permissions.includes(id);const groups=[...new Set(adminBoot.modules.map(m=>m.group))];return `<div class="admin-shell"><aside class="admin-sidebar"><a href="/admin" data-nav class="admin-brand"><span class="logo-mark">A</span><span>astrallab<small>ULTIMATE ECOMMARCE</small></span></a><div class="workspace-select"><span class="workspace-dot">✧</span><div>Ultimate workspace<small>One store · every possibility</small></div><span>⌄</span></div><div class="nav-group">WORKSPACE</div><a data-nav class="admin-nav ${currentModule==='dashboard'?'active':''}" href="/admin">${icon('grid')} Overview</a>${allowed('pos')?`<a data-nav class="admin-nav ${currentModule==='pos'?'active':''}" href="/admin/pos">${icon('pos')} Point of sale <span class="nav-pill">POS</span></a>`:''}${allowed('reports')?`<a data-nav class="admin-nav ${currentModule==='reports'?'active':''}" href="/admin/reports">${icon('chart')} Reports & analytics</a>`:''}${allowed('inventory')?`<a data-nav class="admin-nav ${currentModule==='inventory'?'active':''}" href="/admin/inventory">${icon('layers')} Inventory</a>`:''}${groups.map(group=>`<div class="nav-group">${group.toUpperCase()}</div>${adminBoot.modules.filter(m=>m.group===group).map(m=>`<a data-nav class="admin-nav ${currentModule===m.id?'active':''}" href="/admin/${m.id}">${icon(m.icon)}${esc(m.name)}</a>`).join('')}`).join('')}<div class="nav-group">DESIGN & STORE</div><a data-nav href="/admin/themes" class="admin-nav ${currentModule==='themes'?'active':''}">${icon('themes')} Layouts & color packs <span class="nav-pill">7</span></a>${allowed('media')?`<a data-nav href="/admin/media" class="admin-nav ${currentModule==='media'?'active':''}">${icon('image')} Media library</a>`:''}${allowed('settings')?`<a data-nav href="/admin/settings" class="admin-nav ${currentModule==='settings'?'active':''}">${icon('settings')} Store settings</a>`:''}<a href="/" class="sidebar-store-link">Visit your storefront ↗</a><div class="admin-user"><span class="user-avatar">${esc(adminBoot.user.name[0])}</span><div>${esc(adminBoot.user.name)}<small>Local demo workspace</small></div><button id="logout" title="Sign out">↪</button></div></aside><main class="admin-main"><header class="admin-topbar"><div class="breadcrumbs">Workspace <span>/</span> <b>${esc(currentModule==='dashboard'?'Overview':adminBoot.modules.find(m=>m.id===currentModule)?.name||currentModule.charAt(0).toUpperCase()+currentModule.slice(1))}</b></div><div class="admin-top-actions"><span class="demo-chip"><i></i> LOCAL DEMO</span><a href="/" target="_blank" class="text-btn">View store ↗</a><span class="user-avatar">A</span></div></header><div class="admin-content">${content}</div><footer class="admin-footer"><span>Ultimate Ecommarce By Astrallab</span><span>One connected backend · ${modulesCount()} modules · 7 themes</span></footer></main></div>`}
const modulesCount=()=>adminBoot?.modules.length||0;
function heading(title,description,action=''){return `<div class="admin-page-heading"><div><div class="eyebrow">YOUR BUSINESS, CONNECTED</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function metric(label,value,sub,ico){return `<div class="metric"><div><span>${label}</span>${icon(ico)}</div><strong>${value}</strong><small>${sub}</small></div>`}
function chartHtml(data){const max=Math.max(...data.map(d=>d.revenue),1);const points=data.map((d,i)=>`${i/(data.length-1)*640},${150-d.revenue/max*125}`).join(' ');return `<div class="chart"><div class="chart-axis"><span>${money(max,true)}</span><span>${money(max/2,true)}</span><span>0</span></div><svg viewBox="0 0 640 180" role="img" aria-label="Revenue over the last fourteen days"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#8f7aeb" stop-opacity=".25"/><stop offset="1" stop-color="#8f7aeb" stop-opacity="0"/></linearGradient></defs>${[25,87,150].map(y=>`<line x1="0" y1="${y}" x2="640" y2="${y}" stroke="#eef0f5" stroke-dasharray="4"/>`).join('')}<polygon points="0,150 ${points} 640,150" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#8064df" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${data.map((d,i)=>`<circle cx="${i/(data.length-1)*640}" cy="${150-d.revenue/max*125}" r="3" fill="#8064df"><title>${d.date}: ${money(d.revenue,true)}</title></circle>`).join('')}</svg><div class="chart-dates"><span>${date(data[0].date)}</span><span>${date(data[Math.floor(data.length/2)].date)}</span><span>${date(data.at(-1).date)}</span></div></div>`}
async function dashboardPage(report=false){const d=await api(report?'/api/reports':'/api/dashboard');return adminShell(`${heading(report?'A clearer picture.':'Good things are growing. ✧',report?'Sales, costs and operations, calculated from your shared database.':'Here’s what’s happening across your store today.',`<a href="/" target="_blank" class="btn admin-btn outline">${icon('store')} Visit storefront ↗</a>`)}<div class="overview-banner"><div><span class="live-dot"></span>Your entire commerce stack, finally together.</div><span>${modulesCount()} connected modules <b>·</b> 7 storefront themes</span></div><div class="metrics-grid">${metric('Total sales',money(d.revenue,true),'Excludes cancelled & refunded orders','wallet')}${metric('Total orders',d.orders,'Storefront and POS, combined','orders')}${metric('Customers',d.customers,'Your growing community','users')}${metric(report?'Estimated profit':'Products',report?money(d.profit,true):d.products,report?'Sales − product costs − expenses':d.lowStock.length+' products need a stock check','package')}</div><div class="dashboard-columns"><section class="panel sales-panel"><div class="panel-heading"><div><h2>Sales at a glance</h2><p>Your last 14 days of store activity</p></div><span class="pill">Last 14 days ⌄</span></div><div class="chart-summary"><strong>${money(d.chart.reduce((s,x)=>s+x.revenue,0),true)}</strong><span>Recorded sales</span></div>${chartHtml(d.chart)}</section><section class="panel status-panel"><div class="panel-heading"><h2>Order overview</h2><a data-nav href="/admin/orders">View all ↗</a></div><div class="order-ring" style="--ring:${Math.round((d.statuses.delivered||0)/Math.max(d.orders,1)*100)}%"><div><strong>${d.orders}</strong><small>Total orders</small></div></div><div class="status-legend">${Object.entries(d.statuses).filter(([,n])=>n).map(([s,n])=>`<div><span><i class="dot ${s}"></i>${s}</span><b>${n}</b></div>`).join('')}</div></section></div><div class="dashboard-columns lower"><section class="panel"><div class="panel-heading"><div><h2>Recent orders</h2><p>A little momentum, one order at a time.</p></div><a data-nav href="/admin/orders">View all orders ↗</a></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Status</th><th>Total</th></tr></thead><tbody>${d.recent.map(o=>`<tr data-order="${o.id}"><td><b>${esc(o.number)}</b><small>${date(o.created_at)}</small></td><td>${esc(o.customer_name)}</td><td>${badge(o.status)}</td><td><b>${money(o.total,true)}</b></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-heading"><h2>Your bestsellers</h2><a data-nav href="/admin/products">Products ↗</a></div><div class="bestsellers">${d.top.map((p,i)=>`<div><span class="rank">${i+1}</span><img src="${esc(productById(p.product_id)?.image||'')}" alt="${esc(p.name)}"><span><b>${esc(p.name)}</b><small>${p.quantity} units sold</small></span><strong>${money(p.revenue,true)}</strong></div>`).join('')}</div></section></div>${report?`<div class="metrics-grid">${metric('Product costs',money(d.cogs,true),'Cost at the time of purchase','package')}${metric('Expenses',money(d.expenses,true),'Recorded business expenses','wallet')}${metric('Average order',money(d.average,true),'Non-cancelled orders','chart')}${metric('Estimated profit',money(d.profit,true),'Before payment and other unrecorded fees','spark')}</div>`:`<section class="workspace-shortcuts"><a data-nav href="/admin/pos"><span>⊞</span><div>Ready to make a sale?<small>Open your connected point of sale.</small></div>↗</a><a data-nav href="/admin/themes"><span>◐</span><div>A new look. The same store.<small>Choose layouts, palettes and display modes.</small></div>↗</a><a data-nav href="/admin/products"><span>＋</span><div>Something new to share?<small>Add your next bestselling product.</small></div>↗</a></section>`}`)}
function recordColumns(module){if(module==='orders')return [{key:'number',label:'Order'},{key:'customer_name',label:'Customer'},{key:'total',label:'Total'},{key:'channel',label:'Channel'},{key:'status',label:'Status'},{key:'payment_status',label:'Payment'}];if(['payments','refunds'].includes(module))return ['name','order_id','amount','status','created_at'].map(key=>({key,label:title(key)}));if(module==='audit')return ['name','module','actor','created_at'].map(key=>({key,label:title(key)}));const spec=adminBoot.modules.find(m=>m.id===module);const picked=spec.fields.filter(f=>!['password','textarea'].includes(f.type)&&!['image','slug','tags','seo_title','email'].includes(f.key)).slice(0,5);if(!picked.some(f=>f.key==='status')&&spec.fields.some(f=>f.key==='status'))picked.push(spec.fields.find(f=>f.key==='status'));return picked}
const title=value=>value.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
function cell(record,column){const v=record[column.key];if(column.key==='status'||column.key==='payment_status')return badge(v);if(column.key==='created_at')return date(v);if(['price','cost','amount','unit_cost'].includes(column.key))return money(v);if(column.key==='total')return money(v,true);if(column.key==='name')return `<div class="table-product">${record.image?`<img src="${esc(record.image)}" alt="">`:''}<span><b>${esc(v)}</b>${record.sku?`<small>${esc(record.sku)}</small>`:''}</span></div>`;if(column.type==='relation')return esc(adminCache[column.source]?.find(r=>r.id===v)?.name||v||'—');return esc(v??'—')}
async function modulePage(id){const spec=adminBoot.modules.find(m=>m.id===id);if(!spec)return adminShell(errorBox('This module is not available to your role.'));records=await api('/api/records/'+id);recordPage=1;recordSearch='';for(const f of spec.fields.filter(f=>f.type==='relation'))if(!adminCache[f.source])try{adminCache[f.source]=await api('/api/records/'+f.source)}catch{}return adminShell(`${heading(esc(spec.name),esc(spec.description||'Manage your '+spec.name.toLowerCase()+' in one connected workspace.'),`<div class="heading-actions"><a href="/api/export/${id}" class="btn admin-btn outline">Export CSV ↧</a>${!spec.readonly?`<label class="btn outline">Import CSV<input type="file" id="csv-import" accept=".csv,text/csv" hidden></label>`:""}${!spec.readonly?`<button class="btn admin-btn" id="new-record">＋ Add ${esc(spec.name.replace(/s$/,''))}</button>`:''}</div>`)}<section class="panel data-panel"><div class="data-toolbar"><div class="data-tabs"><button class="active" data-record-status="">All records <span>${records.length}</span></button><button data-record-status="active">Active</button><button data-record-status="draft">Draft</button></div><label class="admin-search">⌕ <input id="record-search" placeholder="Search ${esc(spec.name.toLowerCase())}…" aria-label="Search records"></label></div><div id="records-content"></div></section>`)}
function renderRecords(status=''){const spec=adminBoot.modules.find(m=>m.id===currentModule);if(!spec||!$('#records-content'))return;let filtered=records.filter(r=>(!status||r.status===status)&&(!recordSearch||JSON.stringify(r).toLowerCase().includes(recordSearch.toLowerCase())));const columns=recordColumns(currentModule);const pages=Math.max(1,Math.ceil(filtered.length/10));recordPage=Math.min(recordPage,pages);const slice=filtered.slice((recordPage-1)*10,recordPage*10);$('#records-content').innerHTML=`<div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th>${esc(c.label)}</th>`).join('')}<th class="table-action-heading">Actions</th></tr></thead><tbody>${slice.map(r=>`<tr>${columns.map(c=>`<td>${cell(r,c)}</td>`).join('')}<td class="row-actions">${currentModule==='orders'?`<button data-order="${r.id}">View ↗</button>`:!spec.readonly?`${currentModule==='pages'?`<button data-go="/admin/builder?id=${r.id}">Builder</button>`:''}<button data-edit="${r.id}" aria-label="Edit ${esc(r.name)}">Edit</button><button data-delete="${r.id}" aria-label="Delete ${esc(r.name)}">×</button>`:'—'}</td></tr>`).join('')||`<tr><td colspan="${columns.length+1}"><div class="empty small"><span>◇</span><h3>No records yet.</h3><p>Start with your first ${esc(spec.name.toLowerCase().replace(/s$/,''))}.</p></div></td></tr>`}</tbody></table></div><div class="table-pagination"><span>${filtered.length?'Showing '+((recordPage-1)*10+1)+'–'+Math.min(recordPage*10,filtered.length)+' of '+filtered.length+' records':'0 records'}</span><div><button data-page="-1" ${recordPage===1?'disabled':''}>←</button><b>${recordPage} / ${pages}</b><button data-page="1" ${recordPage===pages?'disabled':''}>→</button></div></div>`}
async function recordEditor(id){const spec=adminBoot.modules.find(m=>m.id===currentModule);const record=id?records.find(r=>r.id===Number(id)):null;for(const f of spec.fields.filter(f=>f.type==='relation'))try{adminCache[f.source]=await api('/api/records/'+f.source)}catch{}activeDialog={kind:currentModule,id:record?.id};$('#editor-body').innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">${esc(spec.name)}</span><h2>${record?'Edit record':'Something new.'}</h2></div><button data-close-dialog>×</button></div><form id="record-form"><div class="form-grid">${spec.fields.map(f=>{const value=record?.[f.key]??'';if(f.type==='textarea')return `<label class="wide">${esc(f.label)}<textarea name="${f.key}">${esc(value)}</textarea></label>`;if(f.type==='select'||f.type==='relation'){const options=f.type==='select'?f.options.map(o=>({id:o,name:title(o)})):(adminCache[f.source]||[]).map(r=>({id:r.id,name:r.name}));return `<label>${esc(f.label)}<select name="${f.key}">${f.type==='relation'?'<option value="">Choose…</option>':''}${options.map(o=>`<option value="${esc(o.id)}" ${String(value)===String(o.id)?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label>`}return `<label>${esc(f.label)}<input name="${f.key}" type="${f.type==='password'?'password':f.type==='number'?'number':'text'}" ${f.type==='number'?'step="any" min="0"':''} value="${f.type==='password'?'':esc(value)}" ${f.required?'required':''}></label>`}).join('')}</div><p class="form-error"></p><div class="dialog-footer"><button type="button" class="btn outline" data-close-dialog>Cancel</button><button class="btn admin-btn">Save changes ↗</button></div></form>`;$('#editor').showModal()}
async function orderDialog(id){const o=await api('/api/orders/'+id);activeDialog={kind:'orders',id:o.id};const next={pending:['confirmed','cancelled'],confirmed:['processing','shipped','cancelled'],processing:['shipped','cancelled'],shipped:['delivered','cancelled'],delivered:['refunded'],refunded:[],cancelled:[]}[o.status];$('#editor-body').innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">ORDER DETAILS</span><h2>${esc(o.number)}</h2></div><button data-close-dialog>×</button></div><div class="order-dialog-meta"><div><b>${esc(o.customer_name)}</b><p>${esc(o.email)}<br>${esc(o.phone)}<br>${esc(o.address)}</p></div><div>${badge(o.status)} ${badge(o.payment_status)}<p>${date(o.created_at)} · ${esc(o.channel)}</p></div></div><div class="order-line-items">${o.items.map(i=>`<div><img src="${esc(i.image)}" alt=""><span><b>${esc(i.name)}</b><small>${esc(i.sku)} · ${i.quantity} units</small></span><strong>${money(i.unit_price*i.quantity,true)}</strong></div>`).join('')}</div><div class="summary-line"><span>Discount</span><b>−${money(o.discount,true)}</b></div><div class="summary-line"><span>Shipping + tax</span><b>${money(o.shipping+o.tax,true)}</b></div><div class="summary-line total"><span>Total</span><b>${money(o.total,true)}</b></div><p class="muted">Cancellation and refund restock items exactly once. Refunds here update the local ledger; they do not send money through a payment provider.</p><div class="order-actions">${next.map(s=>`<button class="btn ${['cancelled','refunded'].includes(s)?'danger':'admin-btn'}" data-order-status="${s}" data-id="${o.id}">${s==='refunded'?'Refund & restock':s==='cancelled'?'Cancel & restock':'Mark '+s}</button>`).join('')}${o.payment_status==='pending'&&!['cancelled','refunded'].includes(o.status)?`<button class="btn outline" data-order-paid="${o.id}">Mark payment received</button>`:''}<button class="btn outline" onclick="window.print()">Print receipt</button></div>`;$('#editor').showModal()}
async function inventoryPage(){const data=await api('/api/inventory');return adminShell(`${heading('Inventory, in sync.','Every checkout, POS sale, return and received purchase updates this stock.')}<div class="metrics-grid">${metric('Total units',data.products.reduce((s,p)=>s+p.stock,0),'Across the shared catalog','layers')}${metric('Low stock',data.products.filter(p=>p.stock<10).length,'Products with fewer than 10 units','bell')}${metric('Stock value',money(data.products.reduce((s,p)=>s+p.stock*(p.cost||0),0)),'At current cost price','wallet')}${metric('Movements',data.movements.length,'Latest 300 recorded changes','history')}</div><section class="panel"><div class="panel-heading"><h2>Stock movements</h2><a data-nav href="/admin/products">Manage product stock ↗</a></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Change</th><th>Reason</th><th>Reference</th><th>Recorded</th></tr></thead><tbody>${data.movements.slice(0,60).map(m=>`<tr><td>${esc(data.products.find(p=>p.id===m.product_id)?.name||'Product #'+m.product_id)}</td><td class="${m.delta>0?'positive':'negative'}">${m.delta>0?'+':''}${m.delta}</td><td>${esc(m.reason)}</td><td>${esc(m.reference)}</td><td>${date(m.created_at)}</td></tr>`).join('')}</tbody></table></div></section>`)}
async function settingsPage(){const s=await api('/api/settings');return adminShell(`${heading('Make it your own.','Your store identity, currency, tax and storefront defaults.')}<section class="panel settings-panel"><form id="settings-form"><h2>Store identity</h2><div class="form-grid">${field('name','Platform name','text',s.name,true)}${field('tagline','Tagline','text',s.tagline)}${field('email','Contact email','email',s.email,true)}${field('phone','Phone','text',s.phone)}${field('address','Address','text',s.address)}<label>Currency<select name="currency">${['BDT','USD','EUR','GBP'].map(x=>`<option ${x===s.currency?'selected':''}>${x}</option>`).join('')}</select></label>${field('tax_rate','Checkout tax rate (%)','number',s.tax_rate)}<a data-nav href="/admin/themes" class="text-btn">Manage layouts and color packs ↗</a></div><p class="form-error"></p><button class="btn admin-btn">Save store settings ↗</button></form></section>`)}
async function mediaPage(){const media=await api('/api/media');return adminShell(`${heading('A home for your visuals.','Upload product and content images. PNG, JPEG or WebP, up to 5 MB.',`<label class="btn admin-btn">＋ Upload image<input type="file" id="media-upload" accept="image/png,image/jpeg,image/webp" hidden></label>`)}<div class="media-grid">${[...media,...boot.products.map(p=>({image:p.image,name:p.name}))].map(m=>`<article class="media-card"><img src="${esc(m.image)}" alt="${esc(m.name)}"><div><b>${esc(m.name)}</b><button data-copy="${esc(m.image)}">Copy URL ↗</button></div></article>`).join('')}</div>`)}
async function posPage(){return adminShell(`${heading('A great day to make a sale.','Your point of sale uses the same catalog, stock and order ledger.')}<div class="pos-layout"><section class="panel"><div class="panel-heading"><h2>Quick product selection</h2><input id="pos-search" class="plain-search" placeholder="Search products…"></div><div class="pos-products" id="pos-products">${boot.products.filter(p=>p.stock>0).map(p=>`<button data-pos-add="${p.id}"><img src="${esc(p.image)}" alt="${esc(p.name)}"><b>${esc(p.name)}</b><span>${money(p.price)}</span><small>${p.stock} in stock</small></button>`).join('')}</div></section><aside class="panel pos-bag"><h2>Current sale</h2><div id="pos-items"></div><form id="pos-form">${field('customer_name','Customer name','text','Walk-in Customer',true)}${field('email','Receipt email','email','walkin@astrallab.local',true)}<p>Payment method: cash · Sale is marked paid and delivered.</p><button class="btn admin-btn full">Complete sale ↗</button><p class="form-error"></p></form></aside></div>`)}
function renderPosItems(){if(!$('#pos-items'))return;$('#pos-items').innerHTML=posCart.length?posCart.map((i,n)=>{const p=productById(i.product_id);return `<div><span>${esc(p.name)}<small>${money(p.price)} × ${i.quantity}</small></span><button data-pos-remove="${n}">×</button></div>`}).join('')+`<div class="pos-total">Total <strong>${money(posCart.reduce((s,i)=>s+productById(i.product_id).price*i.quantity,0))}</strong></div>`:'<div class="empty small"><p>Choose a product to start a sale.</p></div>'}
let builderPageRecord,builderSections=[];
async function builderPage(){const id=Number(new URLSearchParams(location.search).get('id'));const pages=await api('/api/records/pages');builderPageRecord=pages.find(p=>p.id===id);if(!builderPageRecord)return adminShell(errorBox('Create a page first, then open its builder.'));try{builderSections=JSON.parse(builderPageRecord.content);if(!Array.isArray(builderSections))throw Error()}catch{builderSections=[{type:'text',title:builderPageRecord.name,body:builderPageRecord.content||''}]}
 return adminShell(`${heading('Build a little possibility.','Compose published pages with hero, text, product-grid and call-to-action sections.',`<div class="heading-actions"><a href="/page/${esc(builderPageRecord.slug)}" target="_blank" class="btn outline">Preview page ↗</a><button class="btn admin-btn" id="save-builder">Save page ↗</button></div>`)}<section class="panel builder-toolbar"><h2>${esc(builderPageRecord.name)}</h2><div>${['hero','text','products','cta'].map(t=>`<button class="btn outline" data-add-section="${t}">＋ ${title(t)}</button>`).join('')}</div></section><div id="builder-sections"></div>`)}
function renderBuilder(){if(!$('#builder-sections'))return;$('#builder-sections').innerHTML=builderSections.map((s,i)=>`<section class="panel section-editor"><div class="section-editor-controls"><b>${i+1}. ${title(s.type)} section</b><button data-section-move="${i}" data-direction="-1" aria-label="Move section up">↑</button><button data-section-move="${i}" data-direction="1" aria-label="Move section down">↓</button><button data-section-delete="${i}">×</button></div><div class="section-editor-grid"><div class="form-grid"><label>Heading<input data-section-field="title" data-index="${i}" value="${esc(s.title)}"></label>${s.type!=='products'?`<label>Text<textarea data-section-field="body" data-index="${i}">${esc(s.body)}</textarea></label>`:''}${s.type==='hero'?`<label>Image URL<input data-section-field="image" data-index="${i}" value="${esc(s.image||'')}"></label>`:''}</div><div class="section-preview">${sectionHtml(s)}</div></div></section>`).join('')||'<div class="empty">Add a section to start your page.</div>'}
async function renderBase(){document.title='Ultimate Ecommarce By Astrallab';if(!boot){boot=await api('/api/bootstrap');csrf=boot.csrf}
 if(location.pathname.startsWith('/admin')){document.body.classList.add('is-admin');try{if(!adminBoot)adminBoot=await api('/api/admin/bootstrap')}catch(e){$('#app').innerHTML=`<div class="admin-login"><span class="logo-mark">A</span><h1>Your ultimate workspace.</h1><p>Ultimate Ecommarce By Astrallab</p><a href="/demo" class="btn admin-btn full">Open local admin demo ↗</a><span class="login-divider">or sign in with your team account</span><form id="admin-login-form" class="stack-form">${field('email','Email','email','',true)}${field('password','Password','password','',true)}<button class="btn outline full">Sign in</button><p class="form-error"></p></form><a href="/" class="text-btn">← Back to storefront</a></div>`;return}
  currentModule=location.pathname.split('/')[2]||'dashboard';if(currentModule==='dashboard'&&!adminBoot.user.permissions.includes('*')&&!adminBoot.user.permissions.includes('dashboard')){currentModule=adminBoot.modules[0]?.id||'themes';history.replaceState(null,'','/admin/'+currentModule);}let content;if(currentModule==='dashboard')content=await dashboardPage();else if(currentModule==='reports')content=await dashboardPage(true);else if(currentModule==='inventory')content=await inventoryPage();else if(currentModule==='themes')content=await themesPage();else if(currentModule==='settings')content=await settingsPage();else if(currentModule==='media')content=await mediaPage();else if(currentModule==='pos')content=await posPage();else if(currentModule==='builder')content=await builderPage();else content=await modulePage(currentModule);$('#app').innerHTML=content;if($('#records-content'))renderRecords();if(currentModule==='pos')renderPosItems();if(currentModule==='builder')renderBuilder();
 }else{document.body.classList.remove('is-admin');const p=location.pathname;let html;if(p==='/')html=home();else if(p==='/shop')html=shopPage();else if(p.startsWith('/product/'))html=productPage(p.split('/')[2]);else if(p==='/cart'||p==='/checkout')html=await cartPage(p==='/checkout');else if(p==='/account')html=accountPage();else if(p==='/thank-you')html=receiptPage();else html=contentPage();$('#app').innerHTML=html;if(p==='/account'&&boot.customer){const orders=await api('/api/customer/orders');$('#account-orders').innerHTML=orders.length?orders.map(o=>`<article class="account-order"><b>${esc(o.number)}</b>${badge(o.status)}<span>${money(o.total,true)}</span><small>${date(o.created_at)}</small></article>`).join(''):'<p>No orders yet. Your next favorite is waiting.</p>'}}
}
async function themesPage(){return adminShell(heading('Design your experience.','Independent layouts, color packs and display modes for both sides of your platform.')+await appearanceMarkup(api));}
async function render(){await renderBase();if(boot)paint(boot,location.pathname.startsWith('/admin'));}
installDesignEvents({api,refresh:async()=>{boot=await api('/api/bootstrap');adminBoot=null;await render();},notify:toast});
document.addEventListener('click',async e=>{try{
 const add=e.target.closest('[data-add]');if(add){e.preventDefault();addCart(add.dataset.add);return}
 const detail=e.target.closest('[data-detail-add]');if(detail){addCart(detail.dataset.detailAdd,$('#variant-select')?.value?Number($('#variant-select').value):null);return}
 const link=e.target.closest('a[data-nav]');if(link){e.preventDefault();go(link.getAttribute('href'));return}
 const target=e.target.closest('[data-go]');if(target){go(target.dataset.go);return}
 if(e.target.closest('[data-close-dialog]')){$('#editor').close();return}
 const button=e.target.closest('button');if(!button){const row=e.target.closest("[data-order]");if(row)await orderDialog(row.dataset.order);return;}
 if(button.id==='new-record'){await recordEditor();return}
 if(button.dataset.edit){await recordEditor(button.dataset.edit);return}
 if(button.dataset.delete){if(!confirm('Delete this record? Related business records are protected.'))return;await api('/api/records/'+currentModule+'/'+button.dataset.delete,'DELETE');adminCache={};await render();toast('Record deleted');return}
 const order=e.target.closest('[data-order]');if(order){await orderDialog(order.dataset.order);return}
 if(button.dataset.orderStatus){if(['cancelled','refunded'].includes(button.dataset.orderStatus)&&!confirm('This updates the order and returns its items to stock. Continue?'))return;await api('/api/orders/'+button.dataset.id,'PATCH',{status:button.dataset.orderStatus});$('#editor').close();boot=await api('/api/bootstrap');await render();toast('Order and stock updated');return}
 if(button.dataset.orderPaid){await api('/api/orders/'+button.dataset.orderPaid,'PATCH',{payment_status:'paid'});$('#editor').close();await render();toast('Payment recorded');return}
 if(button.hasAttribute('data-record-status')){$$('.data-tabs button').forEach(b=>b.classList.toggle('active',b===button));renderRecords(button.dataset.recordStatus);return}
 if(button.dataset.page){recordPage+=Number(button.dataset.page);renderRecords($('.data-tabs .active')?.dataset.recordStatus||'');return}
 if(button.dataset.activateTheme){await api('/api/settings','PATCH',{theme:button.dataset.activateTheme});adminBoot=await api('/api/admin/bootstrap');boot=await api('/api/bootstrap');await render();toast('Storefront theme updated. Your data stays connected.');return}
 if(button.dataset.cartQty){const index=Number(button.dataset.cartQty);cart[index].quantity+=Number(button.dataset.delta);if(cart[index].quantity<1)cart.splice(index,1);cartSave();await render();return}
 if(button.hasAttribute('data-cart-remove')){cart.splice(Number(button.dataset.cartRemove),1);cartSave();await render();return}
 if(button.dataset.homeFilter){$$('[data-home-filter]').forEach(b=>b.classList.toggle('active',b===button));$('#home-products').innerHTML=boot.products.filter(p=>button.dataset.homeFilter==='all'||p.tags?.includes(button.dataset.homeFilter)).slice(0,8).map(productCard).join('');return}
 if(button.dataset.posAdd){const product=productById(button.dataset.posAdd);const existing=posCart.find(i=>i.product_id===product.id);if(existing)existing.quantity++;else posCart.push({product_id:product.id,quantity:1});renderPosItems();return}
 if(button.hasAttribute('data-pos-remove')){posCart.splice(Number(button.dataset.posRemove),1);renderPosItems();return}
 if(button.dataset.copy){await navigator.clipboard.writeText(button.dataset.copy);toast('Image URL copied');return}
 if(button.dataset.addSection){builderSections.push({type:button.dataset.addSection,title:'Your next great idea',body:'Tell your story here.',image:''});renderBuilder();return}
 if(button.hasAttribute('data-section-delete')){builderSections.splice(Number(button.dataset.sectionDelete),1);renderBuilder();return}
 if(button.hasAttribute('data-section-move')){const i=Number(button.dataset.sectionMove),n=i+Number(button.dataset.direction);if(n>=0&&n<builderSections.length)[builderSections[i],builderSections[n]]=[builderSections[n],builderSections[i]];renderBuilder();return}
 if(button.id==='save-builder'){await api('/api/records/pages/'+builderPageRecord.id,'PATCH',{...builderPageRecord,content:JSON.stringify(builderSections)});boot=await api('/api/bootstrap');toast('Page sections saved');return}
 if(button.id==='customer-toggle'){customerRegister=!customerRegister;await render();return}
 if(button.id==='customer-logout'){await api('/api/customer/logout','POST',{});boot=await api('/api/bootstrap');await render();return}
 if(button.id==='logout'){await api('/api/logout','POST',{});adminBoot=null;await render();return}
 }catch(error){toast(error.message,true)}});
document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const input=Object.fromEntries(new FormData(form));const submit=form.querySelector('button[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{
 if(form.id==='record-form'){const r=await api('/api/records/'+activeDialog.kind+(activeDialog.id?'/'+activeDialog.id:''),activeDialog.id?'PATCH':'POST',input);$('#editor').close();adminCache={};boot=await api('/api/bootstrap');await render();toast('Saved to your shared workspace');}
 if(form.id==='settings-form'){await api('/api/settings','PATCH',input);adminBoot=await api('/api/admin/bootstrap');boot=await api('/api/bootstrap');await render();toast('Store settings saved');}
 if(form.id==='shop-search')go('/shop?'+new URLSearchParams(input));
 if(form.id==='coupon-form'){sessionStorage.setItem('astrallab-coupon',input.coupon);await render();}
 if(form.id==='checkout-form'){const key=sessionStorage.getItem('astrallab-checkout-key')||crypto.randomUUID();sessionStorage.setItem('astrallab-checkout-key',key);lastReceipt=await api('/api/checkout','POST',{...input,items:cart,coupon:sessionStorage.getItem('astrallab-coupon')||'',shipping_id:Number(sessionStorage.getItem('astrallab-shipping')||boot.shipping[0]?.id),idempotency_key:key});sessionStorage.setItem('astrallab-last-order',JSON.stringify(lastReceipt));cart=[];cartSave();sessionStorage.removeItem('astrallab-checkout-key');sessionStorage.removeItem('astrallab-coupon');boot=await api('/api/bootstrap');go('/thank-you');}
 if(form.id==='track-form'){const r=await api('/api/track','POST',input);$('#track-result').innerHTML=`<div class="receipt-box"><h2>${esc(r.number)}</h2>${badge(r.status)} ${badge(r.payment_status)}<p>${date(r.created_at)} · ${money(r.total,true)}</p>${r.shipments.map(s=>`<p>${esc(s.carrier)} · ${esc(s.name)} · ${esc(s.status)}</p>`).join('')}</div>`;}
 if(form.id==='subscribe-form'){await api('/api/subscribe','POST',input);form.reset();toast('You’re on the list. Good things are coming.');}
 if(form.id==='contact-form'){await api('/api/contact','POST',input);form.reset();toast('Your support ticket has been saved.');}
 if(form.id==='customer-form'){await api('/api/customer/'+(customerRegister?'register':'login'),'POST',input);boot=await api('/api/bootstrap');await render();}
 if(form.id==='admin-login-form'){await api('/api/login','POST',input);adminBoot=null;await render();}
 if(form.id==='pos-form'){const receipt=await api('/api/pos','POST',{...input,items:posCart,idempotency_key:crypto.randomUUID()});posCart=[];boot=await api('/api/bootstrap');await render();await orderDialog(receipt.id);toast('Sale complete. Stock and ledger updated.');}
 }catch(error){const errorNode=form.querySelector('.form-error');if(errorNode)errorNode.textContent=error.message;else toast(error.message,true)}finally{if(submit)submit.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='record-search'){recordSearch=e.target.value;recordPage=1;renderRecords()}if(e.target.id==='pos-search'){const term=e.target.value.toLowerCase();$$('[data-pos-add]').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(term))}if(e.target.dataset.sectionField){builderSections[Number(e.target.dataset.index)][e.target.dataset.sectionField]=e.target.value;const section=e.target.closest('.section-editor');section.querySelector('.section-preview').innerHTML=sectionHtml(builderSections[Number(e.target.dataset.index)])}});
document.addEventListener('change',async e=>{try{if(e.target.id==='store-theme'){go('/?theme='+e.target.value)}if(e.target.id==='shipping-select'){sessionStorage.setItem('astrallab-shipping',e.target.value);await render()}if(e.target.id==='product-sort'){const cards=$$('#shop-products .product-card');const value=e.target.value;cards.sort((a,b)=>{const pa=boot.products.find(p=>a.querySelector('a').getAttribute('href').endsWith(p.slug)),pb=boot.products.find(p=>b.querySelector('a').getAttribute('href').endsWith(p.slug));return value==='low'?pa.price-pb.price:value==='high'?pb.price-pa.price:pa.name.localeCompare(pb.name)});cards.forEach(c=>$('#shop-products').append(c))}if(e.target.id==='csv-import'){const file=e.target.files[0];if(file){const result=await api('/api/import/'+currentModule,'POST',{csv:await file.text()});await render();toast(result.imported+' imported'+(result.errors.length?'; '+result.errors.length+' failed. First error: '+result.errors[0].error:''),result.errors.length>0);}return;}if(e.target.id==='media-upload'){const file=e.target.files[0];if(!file)return;const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});await api('/api/media','POST',{name:file.name,data});await render();toast('Image uploaded');}}catch(error){toast(error.message,true)}});
window.addEventListener('popstate',()=>render().catch(e=>toast(e.message,true)));
render().catch(error=>{$('#app').innerHTML=errorBox(error.message)});
